import"chrome://resources/cr_elements/cr_button/cr_button.js";import"chrome://resources/cr_elements/cr_dialog/cr_dialog.js";import{PrefsMixin}from"chrome://resources/cr_components/settings_prefs/prefs_mixin.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{SecureDnsMode}from"./privacy_page_browser_proxy.js";import{getTemplate}from"./secure_dns_dialog.html.js";const SettingsSecureDnsDialogElementBase=PrefsMixin(PolymerElement);export class SettingsSecureDnsDialogElement extends SettingsSecureDnsDialogElementBase{static get is(){return"settings-secure-dns-dialog"}static get template(){return getTemplate()}onDisableClicked_(){if(this.getPref("dns_over_https.mode").value===SecureDnsMode.OFF){this.dispatchEvent(new CustomEvent("dns-settings-invalid-custom-to-off-mode",{bubbles:true,composed:true}))}else{this.setPrefValue("dns_over_https.mode",SecureDnsMode.OFF)}this.$.dialog.close()}onCancelButtonClicked_(){this.$.dialog.close()}}customElements.define(SettingsSecureDnsDialogElement.is,SettingsSecureDnsDialogElement);